<template>
  <main class="page">
    <nav><button class="brand" @click="router.push('/')"><i>D</i><span>DokiAI<small>MECHANICAL ASSISTANT</small></span></button><button class="ghost" @click="router.push('/dashboard')">返回工作台</button></nav>
    <header class="hero">
      <div><em>AI MECHANICAL DESIGN WORKFLOW · V2</em><h1>AI机械设计助手</h1><p>从需求理解到结构方案，<br>帮助工程设计快速完成概念验证</p><button @click="scrollToInput">开始设计 <b>→</b></button><button class="case-button" @click="showCases = !showCases">查看案例</button></div>
      <div class="hero-visual"><span>STRUCTURE INTELLIGENCE</span><div class="machine"><i/><i/><i/><i/><b>AI</b></div><footer><strong>视觉理解</strong><strong>结构推理</strong><strong>工程输出</strong></footer></div>
    </header>

    <section v-if="showCases" class="cases glass"><header><div><em>INSPIRATION LIBRARY</em><h2>机械设计案例库</h2></div></header><div class="case-grid"><button v-for="item in cases" :key="item.name" @click="useCase(item)"><i>{{ item.icon }}</i><strong>{{ item.name }}</strong><span>{{ item.desc }}</span><b>使用此案例 →</b></button></div></section>

    <section ref="inputSection" class="input-card glass">
      <header><div><em>01 · DESIGN INPUT</em><h2>创建机械设计任务</h2></div><span>支持 PNG · JPG · PDF · 草图</span></header>
      <div class="input-grid"><label class="drop" @dragover.prevent @drop.prevent="dropFiles"><input type="file" multiple accept=".png,.jpg,.jpeg,.webp,.pdf" @change="pickFiles"><i>↥</i><strong>拖放机械图片或任务书</strong><span>AI 将读取可见结构与工程文字</span></label><div class="fields"><input v-model="projectName" placeholder="项目名称，例如：自动送料机构"><textarea v-model="description" placeholder="描述用途、载荷、行程、空间和制造约束，例如：设计一个自动送料机构，用于小型工件连续输送。"/><button :disabled="busy || (!description.trim() && !files.length)" @click="submit">{{ busy ? 'AI 正在分析' : '生成机械方案' }} <b>→</b></button></div></div>
      <ul v-if="files.length" class="file-list"><li v-for="(file,index) in files" :key="file.name"><span>▣</span><div><b>{{ file.name }}</b><small>{{ size(file.size) }}</small></div><button @click="files.splice(index,1)">×</button></li></ul>
    </section>

    <section v-if="busy" class="progress-card glass"><em>MECHANICAL AI PIPELINE</em><h2>AI正在分析机械结构</h2><div class="progress-line"><i :style="{width: progress + '%'}"/></div><div class="steps"><span v-for="(step,index) in steps" :key="step" :class="{done:index < activeStep,active:index===activeStep}"><i>{{ index < activeStep ? '✓' : index + 1 }}</i>{{ step }}</span></div><p>{{ progressText }}</p></section>

    <template v-if="result">
      <section class="result-head"><div><em>AI CONCEPT RESULT</em><h2>{{ result.projectName }}</h2><p>{{ analysis.summary }}</p></div><button @click="exportReport">导出 DOCX 报告 ↓</button></section>
      <section class="result-grid">
        <article class="concept glass"><header><div><em>02 · CONCEPT DESIGN</em><h2>三维概念方案</h2></div><button @click="zoomed=true">⛶ 放大</button></header><div class="concept-board" :class="`scheme-${activeSolution}`"><span>AI CONCEPT / NOT CAD</span><div class="iso-machine"><i/><i/><i/><i/><i/><b>{{ currentSolution.driveType }}</b></div><footer><strong>{{ currentSolution.name }}</strong><small>{{ currentSolution.description }}</small></footer></div><nav class="solutions"><button v-for="(s,index) in solutions" :key="s.id" :class="{active:activeSolution===index}" @click="activeSolution=index"><i>0{{ index+1 }}</i><span><b>{{ s.name }}</b><small>{{ s.driveType }}</small></span></button></nav><div class="trade"><p><b>优势</b>{{ currentSolution.advantages?.join(' · ') }}</p><p><b>权衡</b>{{ currentSolution.tradeoffs?.join(' · ') }}</p></div></article>
        <article class="analysis glass"><header><em>03 · DESIGN ANALYSIS</em><h2>设计分析</h2></header><div class="type"><span>设备类型</span><strong>{{ analysis.equipmentType }}</strong></div><h3>主要组成</h3><ul class="components"><li v-for="(c,index) in analysis.components" :key="c.name"><i>{{ String(index+1).padStart(2,'0') }}</i><div><b>{{ c.name }}</b><span>{{ c.function }}</span></div><small>{{ c.material }}</small></li></ul><h3>工作原理</h3><div class="principle"><template v-for="(p,index) in analysis.workingPrinciple" :key="p"><span>{{ p }}</span><i v-if="index < analysis.workingPrinciple.length-1">↓</i></template></div><h3>设计建议</h3><ul class="advice"><li v-for="r in analysis.recommendations" :key="r">✓ {{ r }}</li></ul></article>
      </section>
      <section class="bottom-grid"><article class="tree glass"><header><em>04 · ASSEMBLY LOGIC</em><h2>装配结构</h2><span>概念结构树 · 非 CAD 装配</span></header><TreeNode :node="analysis.structureTree" /></article><article class="engineering glass"><header><em>05 · ENGINEERING OUTPUT</em><h2>工程辅助资料</h2></header><div><span>参数建议</span><ul><li v-for="p in analysis.parameters" :key="p.name"><b>{{ p.name }}</b><strong>{{ p.value }}</strong><small>{{ p.basis }}</small></li></ul></div><div><span>风险与待确认</span><p v-for="risk in analysis.risks" :key="risk">⚠ {{ risk }}</p></div><footer><span>后续接口</span><i v-for="x in result.futureInterfaces" :key="x">{{ x }}</i></footer></article></section>
    </template>
    <div v-if="zoomed" class="modal" @click="zoomed=false"><div class="concept-board big" :class="`scheme-${activeSolution}`"><span>AI CONCEPT / NOT CAD</span><div class="iso-machine"><i/><i/><i/><i/><i/><b>{{ currentSolution.driveType }}</b></div><footer><strong>{{ currentSolution.name }}</strong><small>{{ currentSolution.description }}</small></footer></div></div>
  </main>
</template>

<script setup>
import { computed, defineComponent, h, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { analyzeMechanicalAssistant, downloadMechanicalAssistantReport } from '../../api/rewrite'
const router=useRouter(), inputSection=ref(), showCases=ref(false), busy=ref(false), progress=ref(0), activeStep=ref(0), result=ref(null), activeSolution=ref(0), zoomed=ref(false); const projectName=ref(''),description=ref(''),files=ref([])
const steps=['图片结构识别','零件关系分析','工作原理判断','设计方案生成']; const progressText=computed(()=>['读取上传资料与视觉证据…','建立机械模块与连接关系…','推断动力路径与装配逻辑…','形成三个可比较的概念方案…'][activeStep.value]||'整理工程资料…'); const analysis=computed(()=>result.value?.analysis||{}); const solutions=computed(()=>analysis.value.solutions||[]); const currentSolution=computed(()=>solutions.value[activeSolution.value]||{})
const cases=[{icon:'↝',name:'自动送料机构设计',desc:'同步带 / 链传动 / 丝杆对比',text:'设计一套自动送料机构，用于小型金属工件连续输送，节拍每分钟20件，要求维护方便。'},{icon:'⚙',name:'齿轮减速机构',desc:'传动比分配与轴系布局',text:'设计两级齿轮减速机构，输入功率1.5kW，需要分析轴、齿轮、箱体和轴承布置。'},{icon:'⌁',name:'机械臂结构设计',desc:'关节、驱动与末端执行器',text:'设计桌面级三轴机械臂概念方案，负载2kg，工作半径600mm。'},{icon:'⇢',name:'输送机设计',desc:'机架、滚筒和张紧结构',text:'设计宽度400mm的轻型皮带输送机，输送距离3m，需要给出驱动和张紧建议。'}]
const TreeNode=defineComponent({name:'TreeNode',props:{node:Object},setup(p){return()=>p.node?h('div',{class:'tree-node'},[h('b',p.node.name),...(p.node.children?.length?[h('div',{class:'tree-children'},p.node.children.map(n=>h(TreeNode,{node:n,key:n.name})))]:[])]):null}})
function scrollToInput(){inputSection.value?.scrollIntoView({behavior:'smooth'})} function useCase(c){projectName.value=c.name;description.value=c.text;showCases.value=false;setTimeout(scrollToInput,50)} function pickFiles(e){addFiles([...e.target.files]);e.target.value=''} function dropFiles(e){addFiles([...e.dataTransfer.files])} function addFiles(next){const allowed=/\.(png|jpe?g|webp|pdf)$/i;files.value=[...files.value,...next.filter(f=>allowed.test(f.name))].slice(0,6)} function size(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB'}
async function submit(){busy.value=true;result.value=null;progress.value=8;activeStep.value=0;const timer=setInterval(()=>{progress.value=Math.min(92,progress.value+4);activeStep.value=Math.min(3,Math.floor(progress.value/24))},700);try{result.value=await analyzeMechanicalAssistant({projectName:projectName.value,description:description.value,files:files.value});progress.value=100;activeStep.value=4;ElMessage.success('机械方案分析完成')}catch(e){ElMessage.error(e.message||'分析失败')}finally{clearInterval(timer);setTimeout(()=>busy.value=false,350)}}
async function exportReport(){try{const blob=await downloadMechanicalAssistantReport(result.value.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${result.value.projectName}-设计辅助报告.docx`;a.click();URL.revokeObjectURL(url);ElMessage.success('DOCX 报告已导出')}catch(e){ElMessage.error(e.message||'报告导出失败')}}
</script>

